initialize(state) {
if (!state.domainState || Object.keys(state.domainState).length === 0) {
state.domainState = {
revenue: 1100000,
grossMargin: 42,
ebitda: 185000,
complianceScore: 50,
marketShare: 100,
governanceQuality: 30,
riskExposure: 50,
revenueHistory: [],
complianceHistory: [],
marketShareHistory: [],
riskHistory: [],
roundEvents: [],
totalCosts: 0
};
}
if (!state.decisions || Object.keys(state.decisions).length === 0) {
state.decisions = {
d1: '', d2: '', d3: '', d4: '', d5: '', d6: ''
};
}
this._updateBriefing(state);
}

validateDecisions(decisions) {
var inputs = document.querySelectorAll('.pricebot-sim-controls input[type="radio"]:checked');
var selected = {};
inputs.forEach(function(inp) { selected[inp.name] = inp.value; });
for (var i = 1; i <= 6; i++) {
var key = 'd' + i;
if (!selected[key]) {
window.mySimulation.uiManager.showNotification(
window.mySimulation.t('select_all_warning'), 'warning'
);
return false;
}
decisions[key] = selected[key];
}
return true;
}

calculateResults(state) {
var d = state.decisions;
var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
var round = this.ROUNDS[roundIdx];
var impacts = {rev: 0, margin: 0, comp: 0, gov: 0, risk: 0, cost: 0};
for (var i = 0; i < round.decisions.length; i++) {
var dec = round.decisions[i];
var chosen = d[dec.id];
var opt = null;
for (var j = 0; j < dec.options.length; j++) {
if (dec.options[j].value === chosen) { opt = dec.options[j]; break; }
}
if (opt) {
impacts.rev += opt.rev;
impacts.margin += opt.margin;
impacts.comp += opt.comp;
impacts.gov += opt.gov;
impacts.risk += opt.risk;
impacts.cost += opt.cost;
}
}
var eventResult = null;
if (round.events && round.events.length > 0) {
var totalProb = 0;
for (var e = 0; e < round.events.length; e++) { totalProb += round.events[e].probability; }
var rand = Math.random() * totalProb;
var acc = 0;
for (var e = 0; e < round.events.length; e++) {
acc += round.events[e].probability;
if (rand <= acc) { eventResult = round.events[e]; break; }
}
if (eventResult) {
impacts.rev += eventResult.revImpact;
impacts.comp += eventResult.compImpact;
impacts.risk += eventResult.riskImpact;
impacts.gov += eventResult.govImpact;
}
}
var ds = state.domainState;
ds.revenue = Math.max(0, ds.revenue + impacts.rev);
ds.grossMargin = Math.max(0, Math.min(80, ds.grossMargin + impacts.margin));
ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore + impacts.comp));
ds.governanceQuality = Math.max(0, Math.min(100, ds.governanceQuality + impacts.gov));
ds.riskExposure = Math.max(0, Math.min(100, ds.riskExposure + impacts.risk));
ds.totalCosts += Math.abs(impacts.cost);
var marketDelta = (impacts.rev / 50000) + (impacts.comp / 20) - (impacts.risk / 25);
ds.marketShare = Math.max(50, Math.min(150, ds.marketShare + marketDelta));
ds.ebitda = Math.round(ds.revenue * (ds.grossMargin / 100) * 0.4);
ds.revenueHistory.push(ds.revenue);
ds.complianceHistory.push(ds.complianceScore);
ds.marketShareHistory.push(ds.marketShare);
ds.riskHistory.push(ds.riskExposure);
if (eventResult) { ds.roundEvents.push(eventResult.name); } else { ds.roundEvents.push('No event'); }
var eventPanel = document.getElementById('eventPanel');
var eventText = document.getElementById('eventText');
if (eventPanel && eventText && eventResult) {
eventPanel.style.display = 'block';
var evKey = 'r' + (roundIdx + 1) + '_ev' + round.events.indexOf(eventResult) + '_';
eventText.innerHTML = '<strong>' + this._t(evKey + 'name', eventResult.name) + '</strong><br>' + this._t(evKey + 'desc', eventResult.description);
} else if (eventPanel) {
