}
var self = this;
var _cp = state.currentPeriod;
if (state === window.mySimulation.state) {
setTimeout(function() {
self._updateBriefing({currentPeriod: _cp + 1, domainState: ds});
}, 500);
}
return {
period: state.currentPeriod,
roundTitle: round.title,
revenueImpact: impacts.rev,
