getPerformanceSummary(history) {
if (!history.length) return {};
var lastRecord = history[history.length - 1];
var ds = lastRecord.domainState || {};
var finalRevenue = ds.revenue || 1100000;
var finalCompliance = ds.complianceScore || 50;
var finalMargin = ds.grossMargin || 42;
var finalMarketShare = ds.marketShare || 100;
var revenueTarget = 1300000;
var revenueScore = Math.min(100, Math.max(0, ((finalRevenue - 900000) / (revenueTarget - 900000)) * 100));
var marginScore = Math.min(100, Math.max(0, ((finalMargin - 35) / (48 - 35)) * 100));
var complianceScoreVal = Math.min(100, Math.max(0, finalCompliance));
var marketShareScore = Math.min(100, Math.max(0, ((finalMarketShare - 60) / (140 - 60)) * 100));
var composite = (revenueScore * 0.25) + (marginScore * 0.25) + (complianceScoreVal * 0.30) + (marketShareScore * 0.20);
var performance = this._t('perf_needs', 'Needs Improvement');
if (composite >= 75) performance = this._t('perf_excellent', 'Excellent');
else if (composite >= 60) performance = this._t('perf_strong', 'Strong');
else if (composite >= 45) performance = this._t('perf_acceptable', 'Acceptable');
var insights = [];
if (revenueScore > 70 && complianceScoreVal > 70) insights.push(this._t('ins_balanced', 'You balanced revenue growth with compliance effectively.'));
if (complianceScoreVal < 40) insights.push(this._t('ins_low_comp', 'Low compliance score suggests significant regulatory liability risk.'));
if (revenueScore < 40) insights.push(this._t('ins_rev_decline', 'Revenue declined substantially. Algorithm constraints may have been too aggressive.'));
if (finalMarketShare < 85) insights.push(this._t('ins_share_loss', 'Market share loss is concerning. Competitive position has weakened.'));
if (composite >= 70) insights.push(this._t('ins_strong', 'Strong overall governance and strategy. The balanced approach paid off.'));
if (insights.length === 0) insights.push(this._t('ins_consider', 'Consider how to better balance optimization with compliance in future scenarios.'));
return {
compositeScore: Math.round(composite),
revenueScore: Math.round(revenueScore),
marginScore: Math.round(marginScore),
complianceScore: Math.round(complianceScoreVal),
marketShareScore: Math.round(marketShareScore),
performance: performance,
insights: insights
};
}

getHint(state, results) {
if (!results) return null;
if (results.risk > 75) return window.mySimulation.t('hint_high_risk');
if (results.compliance < 30) return window.mySimulation.t('hint_low_compliance');
if (results.revenue < 900000) return window.mySimulation.t('hint_revenue_decline');
if (results.governance < 20) return window.mySimulation.t('hint_low_governance');
if (results.compliance > 70 && results.revenue > 1100000) return window.mySimulation.t('hint_balanced');
return null;
}

