_t(key, en) {
// translation lookup at render time; falls back to the original English when the key is missing
var f = window.mySimulation;
var s = (f && typeof f.t === 'function') ? f.t(key) : null;
return (typeof s === 'string' && s && s !== key) ? s : en;
}

_trTitle(v) {
for (var i = 0; i < this.ROUNDS.length; i++) {
if (this.ROUNDS[i].title === v) { return this._t('r' + (i + 1) + '_title', v); }
}
return v;
}

_trEvent(v) {
if (v === 'None') { return this._t('event_none', v); }
for (var i = 0; i < this.ROUNDS.length; i++) {
var evs = this.ROUNDS[i].events || [];
for (var k = 0; k < evs.length; k++) {
if (evs[k].name === v) { return this._t('r' + (i + 1) + '_ev' + k + '_name', v); }
}
}
return v;
}

_updateBriefing(state) {
var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
var round = this.ROUNDS[idx];
var rk = 'r' + (idx + 1) + '_';
var briefEl = document.getElementById('briefingText');
if (briefEl) {
briefEl.innerHTML = '<strong>' + this._t(rk + 'title', round.title) + '</strong><br><br>' + this._t(rk + 'brief', round.briefing);
}
var container = document.getElementById('decisionsContainer');
if (!container) return;
container.innerHTML = '';
for (var i = 0; i < round.decisions.length; i++) {
var dec = round.decisions[i];
var group = document.createElement('div');
group.className = 'decision-group';
var heading = document.createElement('h5');
heading.textContent = this._t(rk + dec.id + '_label', dec.label);
group.appendChild(heading);
for (var j = 0; j < dec.options.length; j++) {
var opt = dec.options[j];
var optDiv = document.createElement('div');
optDiv.className = 'decision-option';
var radio = document.createElement('input');
radio.type = 'radio';
radio.name = dec.id;
radio.value = opt.value;
radio.id = dec.id + '_' + opt.value;
var lbl = document.createElement('label');
lbl.htmlFor = dec.id + '_' + opt.value;
lbl.innerHTML = '<span class="option-tag">' + opt.value.toUpperCase() + ':</span> ' + this._t(rk + dec.id + '_' + opt.value, opt.text);
optDiv.appendChild(radio);
optDiv.appendChild(lbl);
group.appendChild(optDiv);
}
container.appendChild(group);
}
}

}

document.addEventListener('DOMContentLoaded', function() {
window.mySimulation = new USF.SimulationFramework();
/* score mirror 2026-11-11: copies the score this adapter already computes into domainState.performance.overallScore */
(function (P) {
  var orig = P.calculateResults;
  var ok = function (v) { v = parseFloat(v); return isFinite(v) && v >= 0 && v <= 100; };
  P.calculateResults = function (s) {
    var r = orig.apply(this, arguments);
    try {
      var ds = s && s.domainState;
      if (ds && !(ds.performance && ok(ds.performance.overallScore) && !ds.performance.mirrored)) {
        var v = null, c = [ds.overallScore, ds.score, ds.totalScore, ds.composite, ds.compositeScore], i;
        for (i = 0; i < c.length && v === null; i++) { if (ok(c[i])) { v = parseFloat(c[i]); } }
        if (v === null && typeof this.getPerformanceSummary === 'function') {
          var h = (s.history || []).concat([{ period: s.currentPeriod, decisions: JSON.parse(JSON.stringify(s.decisions || {})), results: r, domainState: ds }]);
          var m = this.getPerformanceSummary(h) || {};
          var k = ['overallScore', 'score', 'totalScore', 'composite', 'finalScore', 'compositeScore', 'performanceScore'];
          for (i = 0; i < k.length && v === null; i++) { if (ok(m[k[i]])) { v = parseFloat(m[k[i]]); } }
        }
        if (v !== null) {
          v = Math.round(v * 10) / 10;
          if (!ds.performance || typeof ds.performance !== 'object') { ds.performance = {}; }
          ds.performance.overallScore = v;
          ds.performance.mirrored = true;
        }
      }
    } catch (e) { }
    return r;
  };
})(PriceBotAdapter.prototype);
window.mySimulation.initialize(new PriceBotAdapter(), {
simulationType: 'pricebot_pricing',
maxPeriods: 5,
autoSaveInterval: 30000
});
});

})();
